from datetime import date, datetime, timedelta

_MONTHS = {name: i for i, name in enumerate(
    "JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC".split(), 1)}
_DAYS = {name: i for i, name in enumerate("SUN MON TUE WED THU FRI SAT".split())}
_FIELDS = ((0, 59, {}), (0, 23, {}), (1, 31, {}), (1, 12, _MONTHS), (0, 7, _DAYS))


def _number(text: str, low: int, high: int, names: dict[str, int]) -> int:
    if text.upper() in names:
        return names[text.upper()]
    if not (text.isascii() and text.isdigit()):
        raise ValueError(f"invalid cron value: {text!r}")
    value = int(text)
    if not low <= value <= high:
        raise ValueError(f"cron value out of range {low}-{high}: {text!r}")
    return value


def _field(text: str, low: int, high: int, names: dict[str, int]) -> set[int]:
    values = set()
    for item in text.split(","):
        base, slash, step = item.partition("/")
        if base == "*":
            first, last = low, high
        else:
            start, dash, end = base.partition("-")
            first = _number(start, low, high, names)
            last = _number(end, low, high, names) if dash else high if slash else first
        every = _number(step, 1, high, {}) if slash else 1
        if first > last:
            raise ValueError(f"invalid cron range: {item!r}")
        values.update(range(first, last + 1, every))
    return values


def _in_five_years(moment: datetime) -> datetime:
    try:
        return moment.replace(year=moment.year + 5)
    except ValueError:  # Feb 29
        return moment.replace(year=moment.year + 5, day=28)


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"cron expression needs 5 fields: {expression!r}")
    minutes, hours, doms, months, dows = (
        _field(text, *spec) for text, spec in zip(fields, _FIELDS))
    dows = {d % 7 for d in dows}
    either = fields[2] != "*" and fields[4] != "*"
    times = sorted((h, m) for h in hours for m in minutes)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = _in_five_years(after)
    day = start.date()
    while day <= limit.date():
        if day.month not in months:
            day = date(day.year + day.month // 12, day.month % 12 + 1, 1)
            continue
        dom, dow = day.day in doms, day.isoweekday() % 7 in dows
        if dom or dow if either else dom and dow:
            earliest = (start.hour, start.minute) if day == start.date() else (0, 0)
            hm = next((t for t in times if t >= earliest), None)
            if hm is not None:
                found = datetime.combine(day, datetime.min.time()).replace(
                    hour=hm[0], minute=hm[1])
                if found <= limit:
                    return found
                break
        day += timedelta(days=1)
    raise ValueError(f"cron expression never fires within five years: {expression!r}")
'''
